  if (_isDisposed == true) {
    return;
  }
  SwingUtilities.invokeLater(new Runnable(){
    public void run(){
      _categoryExplorerTree.getExplorerModel().addLogRecord(lr);
      _table.getFilteredLogTableModel().addLogRecord(lr);
      updateStatusLabel();
    }
  }
);
}

