public int appendLoopOnAppenders(LoggingEvent event){
  int size=0;
  Appender appender;
  if (appenderList != null) {
    size=appenderList.size();
    for (int i=0; i < size; i++) {
      appender=(Appender)appenderList.elementAt(i);
      appender.doAppend(event);
    }
  }
  return size;
}

